PRAGMA foreign_keys=ON;
CREATE TABLE contexts(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('academic','organization','personal')),display_name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,archived_at TEXT);
CREATE TABLE tasks(id TEXT PRIMARY KEY,context_id TEXT REFERENCES contexts(id),title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 240),kind TEXT NOT NULL,description TEXT,status TEXT NOT NULL CHECK(status IN ('todo','doing','blocked','done','archived')),priority TEXT NOT NULL,due_json TEXT NOT NULL,due_at_utc TEXT,version INTEGER NOT NULL DEFAULT 1,due_revision INTEGER NOT NULL DEFAULT 1,mutation_id TEXT NOT NULL DEFAULT 'created',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE INDEX tasks_due ON tasks(status,due_at_utc);
CREATE TABLE task_events(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT NOT NULL,event_type TEXT NOT NULL,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL);
CREATE TRIGGER task_insert AFTER INSERT ON tasks BEGIN INSERT INTO task_events(task_id,event_type,after_json,created_at) VALUES(new.id,'created',json_object('title',new.title,'status',new.status,'due',json(new.due_json)),new.updated_at); END;
CREATE TRIGGER task_update AFTER UPDATE ON tasks BEGIN INSERT INTO task_events(task_id,event_type,before_json,after_json,created_at) VALUES(new.id,'updated',json_object('title',old.title,'status',old.status,'due',json(old.due_json)),json_object('title',new.title,'status',new.status,'due',json(new.due_json)),new.updated_at); UPDATE reminder_intents SET state='canceled' WHERE task_id=new.id AND (new.status IN ('done','archived') OR new.deleted_at IS NOT NULL OR due_revision<>new.due_revision); END;
CREATE TABLE sources(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,kind TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 1,paused INTEGER NOT NULL DEFAULT 0,purged_at TEXT,last_sync_at TEXT,coverage_json TEXT);
CREATE TABLE source_items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),generation INTEGER NOT NULL,observed_at TEXT NOT NULL,source_message_at TEXT,local_evidence_available INTEGER NOT NULL,removed_at TEXT);
CREATE TABLE candidates(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),generation INTEGER NOT NULL,fields_json TEXT NOT NULL,issues_json TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,accepted_action TEXT,result_task_id TEXT);
CREATE TABLE candidate_evidence(candidate_id TEXT REFERENCES candidates(id),source_item_id TEXT REFERENCES source_items(id),PRIMARY KEY(candidate_id,source_item_id));
CREATE TABLE review_actions(id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE collector_credentials(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),secret TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE replay_nonces(credential_id TEXT NOT NULL,nonce TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(credential_id,nonce));
CREATE TABLE idempotency_records(scope TEXT NOT NULL,key TEXT NOT NULL,digest TEXT NOT NULL,result_id TEXT NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE source_tombstones(source_id TEXT NOT NULL,generation INTEGER NOT NULL,purged_at TEXT NOT NULL,PRIMARY KEY(source_id,generation));
CREATE TABLE reminder_intents(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),due_revision INTEGER NOT NULL,scheduled_for_utc TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',UNIQUE(task_id,due_revision,scheduled_for_utc));
CREATE INDEX reminders_due ON reminder_intents(state,scheduled_for_utc);
CREATE TABLE notification_inbox(id TEXT PRIMARY KEY,intent_id TEXT UNIQUE NOT NULL,task_id TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),value_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
INSERT INTO settings VALUES(1,'{"timezone":"Asia/Makassar","language":"id","theme":"light"}',1);
CREATE TABLE task_evidence(task_id TEXT NOT NULL REFERENCES tasks(id),source_item_id TEXT NOT NULL REFERENCES source_items(id),approval_event_id TEXT NOT NULL,PRIMARY KEY(task_id,source_item_id));
CREATE TABLE mutation_guards(id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));
